window.docContents[8].resolve({"/releases/#versioned-release-notes":{"contents":"An entry is a file under doc/UsersGuide/Releases/Entries/ that names the version it describes.\nThe sections of this chapter are derived from those versions, so an entry written before a release and merged after one lands in the section for the version it actually shipped in.\nPull requests are checked for an entry, and for naming the version that is under development.\n\n\n","context":"Writing Documentation in Lean with Verso\u0009Release Notes\u0009Verso 4.34.0 (in development)","header":"Versioned Release Note Entries","id":"/releases/#versioned-release-notes"}});